const msg = $input.first().json;
const parts = (msg.payload && msg.payload.parts) || [];
let found = null;
const walk = (ps) => { for (const p of ps) { if (p.filename && p.body && p.body.attachmentId) { found = p; } if (p.parts) walk(p.parts); } };
walk(parts);
if (!found) return [{ json: { error: 'no attachment part', partCount: parts.length } }];
return [{ json: { attachmentId: found.body.attachmentId, filename: found.filename, mimeType: found.mimeType || 'application/pdf', size: found.body.size } }];

const meta = $('Extrair Anexo Meta').first().json;
let status = 0;
let body = null;
try { const r = $('Toolbox Multipart').first().json; status = r.statusCode || 0; body = r.body; } catch (e) { status = -1; body = { error: String(e.message) }; }
const attempts = [{ attempt: 'http-node-multipart', status: status }];
let text = '';
if (status >= 200 && status < 300 && body) {
  if (typeof body === 'string') text = body;
  else if (typeof body.text === 'string') text = body.text;
  else if (typeof body.markdown === 'string') text = body.markdown;
  else if (typeof body.content === 'string') text = body.content;
  else if (body.data && typeof body.data === 'string') text = body.data;
  else text = JSON.stringify(body);
  text = String(text).substring(0, 60000);
}
const extractError = text ? null : ('http-node-multipart:' + status + ' ' + JSON.stringify(body).slice(0, 300));
const L = [
  'Analisa esta fatura de supermercado e retorna APENAS um JSON valido, sem markdown e sem explicacao.',
  '',
  'Schema:',
  '{',
  '  "store": string,',
  '  "document_number": string,',
  '  "date": "YYYY-MM-DD",',
  '  "time": "HH:MM" | null,',
  '  "total": string,',
  '  "total_net": string | null,',
  '  "payment_method": string | null,',
  '  "savings": { "card": string | null, "discounts": string | null },',
  '  "items": [',
  '    { "product": string, "quantity": string, "unit": "kg" | "un" | "lt" | null, "unit_price": string, "total": string, "category": string, "brand": string | null }',
  '  ]',
  '}',
  '',
  'Regras: TODAS as keys em ingles, exatamente como no schema; valores como string com PONTO decimal (ex: "3.49"); category deve ser UMA de: frutas, vegetais, carne, peixe, laticinios, padaria, mercearia, bebidas, congelados, higiene, limpeza, bebe, animais, outros; nao inventes itens - apenas os que estao na fatura; marca do proprio continente = "Continente".',
  ''
];
const prompt = L.join('\n') + '\n\nTexto da fatura:\n' + (text || '(vazio)');
const llmPayload = JSON.stringify({ model: 'glm-5.3-flash', messages: [{ role: 'user', content: prompt }], temperature: 0.1, max_tokens: 16000 });
return [{ json: { filename: meta.filename, textPreview: text.substring(0, 500), textLength: text.length, extractError: extractError, attempts: attempts, llmPayload: llmPayload } }];

const llm = $input.first().json;
const meta = $('Extrair Anexo Meta').first().json;
const raw = (llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content) || '';
function parseNum(s) {
  if (s === null || s === undefined) return null;
  let str = String(s).trim().replace(/[^0-9.,-]/g, '');
  if (!str) return null;
  if (str.includes(',') && str.includes('.')) str = str.replace(/\./g, '').replace(',', '.');
  else if (str.includes(',')) str = str.replace(',', '.');
  const n = parseFloat(str);
  return isNaN(n) ? null : n;
}
const CATS = ['frutas','vegetais','carne','peixe','laticinios','padaria','mercearia','bebidas','congelados','higiene','limpeza','bebe','animais','outros'];
let data = null, parsedOk = false, error = null;
try {
  let js = raw;
  const cb = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (cb) js = cb[1];
  const jm = js.match(/\{[\s\S]*\}/);
  if (jm) data = JSON.parse(jm[0]);
  if (data && Array.isArray(data.items)) parsedOk = true; else error = 'schema: items em falta';
} catch (e) { error = 'JSON parse: ' + e.message; }
if (!data) data = {};
const filenameBase = String(meta.filename || 'fatura').replace(/\.pdf$/i, '');
const m = String(meta.filename || '').match(/(\d{8})[._-]?(\d+)/);
const hintDate = m ? m[1].slice(0,4) + '-' + m[1].slice(4,6) + '-' + m[1].slice(6,8) : null;
const loja = data.store || meta.store || 'DESCONHECIDO';
const numero = String(data.document_number || filenameBase);
const data_doc = data.date || hintDate || '2026-09-21';
const total = data.total != null ? String(data.total) : null;
const itens = (data.items || []).map(it => ({
  product: String(it.product || '').trim(),
  quantity: it.quantity != null ? String(it.quantity) : null,
  unit: it.unit || null,
  unit_price: it.unit_price != null ? String(it.unit_price) : null,
  total: it.total != null ? String(it.total) : null,
  category: CATS.includes(it.category) ? it.category : 'outros',
  brand: it.brand || null
}));
const soma = itens.reduce((acc, it) => acc + (parseNum(it.total) || 0), 0);
const totalNum = parseNum(total);
const record = {
  schema: 'mercado_fatura_v2',
  store: loja, document_number: numero, date: data_doc,
  time: data.time || null, total: total, total_net: data.total_net || null,
  payment_method: data.payment_method || null,
  savings: data.savings || { card: null, discounts: null },
  items: itens,
  check: { items_sum: soma.toFixed(2), document_total: totalNum != null ? totalNum.toFixed(2) : null, difference: totalNum != null ? (totalNum - soma).toFixed(2) : null },
  source: { message_id: '1a0c33e0d7bf8480', file: meta.filename || null, email_received: '2026-09-21' },
  processed_at: new Date().toISOString()
};
const my = data_doc && data_doc.length >= 7 ? data_doc.slice(5,7) + '-' + data_doc.slice(0,4) : '09-2026';
const uploadName = my + '_' + String(loja).replace(/[^A-Za-z0-9]/g, '').slice(0, 20) + '_' + String(numero).replace(/[^A-Za-z0-9]/g, '').slice(0, 25) + '.json';
const webhookPayload = JSON.stringify({ drive_name: uploadName, json: record });
return [{ json: { uploadName: uploadName, parsedOk: parsedOk, error: error, store: loja, total: total, itemCount: itens.length, webhookPayload: webhookPayload } }];

const att = $('Gmail Baixar Anexo').first().json;
const meta = $('Extrair Anexo Meta').first().json;
const b64 = String(att.data || '').replace(/-/g, '+').replace(/_/g, '/');
const buf = Buffer.from(b64, 'base64');
const binaryData = await this.helpers.prepareBinaryData(buf, meta.filename || 'fatura.pdf', meta.mimeType || 'application/pdf');
return [{ json: { filename: meta.filename || 'fatura.pdf', size: buf.length }, binary: { data: binaryData } }];
